import { Fragment, type KeyboardEvent, type ReactNode, useRef, useState } from "react";

export default function RemountOnMouseIn({
  children,
  className,
  duration,
}: {
  children: ReactNode;
  className?: string;
  /**
   * Duration in milliseconds to wait before allowing a remount
   */
  duration?: number;
}) {
  const [key, setKey] = useState(0);
  const lastUpdate = useRef(0);

  const update = () => {
    const now = Date.now();
    if (lastUpdate.current === 0) {
      lastUpdate.current = now;
    }
    if (now - lastUpdate.current > (duration ?? 1000)) {
      setKey((prev) => prev + 1);
      lastUpdate.current = now;
    }
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      update();
    }
  };

  return (
    <button
      type="button"
      className={className}
      onClick={update}
      onMouseEnter={update}
      onKeyDown={handleKeyDown}
    >
      <Fragment key={`force-${key}`}>{children}</Fragment>
    </button>
  );
}

import { useRef, useState } from 'react'
import { getOwnerDocument } from '../utils/owner'
import { useDisposables } from './use-disposables'
import { useEvent } from './use-event'

// Only the necessary props from a DOMRect
type Rect = { left: number; right: number; top: number; bottom: number }

function pointerRectFromPointerEvent(event: PointerEvent): Rect {
  // Center of the pointer geometry
  let offsetX = event.width / 2
  let offsetY = event.height / 2

  return {
    top: event.clientY - offsetY,
    right: event.clientX + offsetX,
    bottom: event.clientY + offsetY,
    left: event.clientX - offsetX,
  }
}

function areRectsOverlapping(a: Rect | null, b: Rect | null) {
  if (!a || !b) {
    return false
  }

  if (a.right < b.left || a.left > b.right) {
    return false
  }

  if (a.bottom < b.top || a.top > b.bottom) {
    return false
  }

  return true
}

export function useActivePress({ disabled = false }: Partial<{ disabled: boolean }> = {}) {
  let target = useRef<HTMLElement | null>(null)
  let [pressed, setPressed] = useState(false)

  let d = useDisposables()

  let reset = useEvent(() => {
    target.current = null
    setPressed(false)
    d.dispose()
  })

  let handlePointerDown = useEvent((event: PointerEvent) => {
    d.dispose() // Cancel any scheduled tasks

    if (target.current !== null) return

    // Keep track of the current element
    target.current = event.currentTarget as HTMLElement

    // We are definitely pressing the element now
    setPressed(true)

    // Setup global handlers to catch events on elements that are not the current element
    {
      let owner = getOwnerDocument(event.currentTarget as Element)!

      // `pointerup` on any element means that we are no longer pressing the current element
      d.addEventListener(owner, 'pointerup', reset, false)

      // `pointerleave` isn't called consistently (if at all) on iOS Safari, so we use `pointermove` instead
      // to determine if we are still "pressing". We also compare the pointer position to the target element
      // so that we can tell if the pointer is still over the element or not.
      d.addEventListener(
        owner,
        'pointermove',
        (event: PointerEvent) => {
          if (target.current) {
            let pointerRect = pointerRectFromPointerEvent(event)
            setPressed(areRectsOverlapping(pointerRect, target.current.getBoundingClientRect()))
          }
        },
        false
      )

      // Whenever the browser decides to fire a `pointercancel` event, we should abort
      d.addEventListener(owner, 'pointercancel', reset, false)
    }
  })

  return {
    pressed,
    pressProps: disabled
      ? {}
      : {
          onPointerDown: handlePointerDown,
          onPointerUp: reset,
          onClick: reset,
        },
  }
}

import "@testing-library/jest-dom"
import { render } from "@testing-library/react"
import { useEffect } from "react"
import { MotionConfig } from "../../../components/MotionConfig"
import { useAnimate } from "../use-animate"

describe("useAnimate", () => {
    test("Types work as expected", () => {
        const Component = () => {
            const [scope, animate] = useAnimate()

            useEffect(() => {
                expect(() => {
                    animate("div", { opacity: 1 })
                }).toThrow()

                animate(scope.current, { opacity: 1 })
            })

            return <div ref={scope} />
        }

        render(<Component />)
    })

    test("Animations removed from scope when finished", () => {
        return new Promise<void>((resolve) => {
            const Component = () => {
                const [scope, animate] = useAnimate()

                useEffect(() => {
                    const animation = animate(
                        scope.current,
                        { opacity: 1 },
                        { duration: 0.1 }
                    )

                    requestAnimationFrame(() => {
                        expect(scope.animations.length).toBe(1)
                    })

                    animation.finished.then(() => {
                        requestAnimationFrame(() => {
                            expect(scope.animations.length).toBe(0)
                            resolve()
                        })
                    })

                    return () => {
                        animation.stop()
                    }
                })

                return <div ref={scope} />
            }

            render(<Component />)
        })
    })

    test("Animates provided animation", async () => {
        return new Promise<void>((resolve) => {
            const Component = () => {
                const [scope, animate] = useAnimate()

                useEffect(() => {
                    animate(
                        scope.current,
                        { opacity: 0.5 },
                        { duration: 0.1 }
                    ).then(() => {
                        expect(scope.current).toHaveStyle("opacity: 0.5;")
                        resolve()
                    })
                })

                return <div ref={scope} />
            }

            render(<Component />)
        })
    })

    test("Stops animations when unmounted", async () => {
        let frameCount = 0
        let unmount = () => {}

        await new Promise<void>((resolve) => {
            const Component = () => {
                const [scope, animate] = useAnimate()

                useEffect(() => {
                    animate(
                        scope.current,
                        { opacity: 0.5 },
                        {
                            duration: 20,
                            onUpdate: () => {
                                frameCount++
                                if (frameCount === 3) {
                                    unmount()
                                    setTimeout(() => {
                                        resolve()
                                    }, 50)
                                }
                            },
                        }
                    )
                })

                return <div ref={scope} />
            }

            unmount = render(<Component />).unmount
        })

        expect(frameCount).toEqual(3)
    })

    test("Applies final value instantly when MotionConfig skipAnimations is true", () => {
        return new Promise<void>((resolve) => {
            const Component = () => {
                const [scope, animate] = useAnimate()

                useEffect(() => {
                    animate(
                        scope.current,
                        { opacity: 0.5 },
                        { duration: 10 }
                    )

                    setTimeout(() => {
                        expect(scope.current).toHaveStyle("opacity: 0.5;")
                        expect(scope.animations.length).toBe(0)
                        resolve()
                    }, 50)
                })

                return <div ref={scope} />
            }

            render(
                <MotionConfig skipAnimations>
                    <Component />
                </MotionConfig>
            )
        })
    })
})

