        await waitFor(() => {
          expect(consoleMock).toHaveBeenLastCalledWith(
            'Checkbox is changing from controlled to uncontrolled. Components should not switch from controlled to uncontrolled (or vice versa). Decide between using a controlled or uncontrolled value for the lifetime of the component.',
          );
        });
      });
    });

    describe('uncontrolled to controlled', () => {
      it('should warn', async () => {
        render(<UnstableComponent />);
        const checkbox = screen.getByRole('checkbox');
        userEvent.click(checkbox);
        await waitFor(() => {
          expect(consoleMock).toHaveBeenLastCalledWith(
            'Checkbox is changing from uncontrolled to controlled. Components should not switch from controlled to uncontrolled (or vice versa). Decide between using a controlled or uncontrolled value for the lifetime of the component.',
          );
        });
      });
    });
  });
});

function ControlledComponent({ defaultChecked }: { defaultChecked?: boolean | undefined }) {
  const [checked, setChecked] = React.useState(defaultChecked ?? false);
  return (
    <div>
      <Checkbox checked={checked} onChange={setChecked} />
      <button type="button" onClick={() => setChecked(false)}>
        Clear value
      </button>
    </div>
  );
}

function UncontrolledComponent({ defaultChecked }: { defaultChecked?: boolean | undefined }) {
  return <Checkbox defaultChecked={defaultChecked} />;
}

function UnstableComponent({ defaultChecked }: { defaultChecked?: boolean | undefined }) {
  const [checked, setChecked] = React.useState(defaultChecked);
  return (
    <div>
      <Checkbox checked={checked} onChange={setChecked} />
      <button type="button" onClick={() => setChecked(undefined)}>
        Clear value
      </button>
    </div>
  );
}

function Checkbox(props: {
  checked?: boolean | undefined;
  defaultChecked?: boolean | undefined;
  onChange?: ((value: boolean) => void) | undefined;
}) {
  const [checked, setChecked] = useControllableState({
    defaultProp: props.defaultChecked ?? false,
    prop: props.checked,
    onChange: props.onChange,
    caller: 'Checkbox',
  });

  return (
    <button
      type="button"
      role="checkbox"
      aria-checked={checked}
      onKeyDown={(e) => void (e.key === 'Enter' && e.preventDefault())}
      onClick={() => setChecked((c) => !c)}
    />
  );
}

import { Activity, version } from "react";
import { act, render, renderHook } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { useCopyToClipboard } from "./use-copy-to-clipboard";

const onReact18 = version.startsWith("18.");

const stubClipboard = (writeText: (value: string) => Promise<void>) => {
  vi.stubGlobal("navigator", { ...navigator, clipboard: { writeText } });
};

describe("useCopyToClipboard", () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.useRealTimers();
    vi.unstubAllGlobals();
  });

  it("keeps copy success visible for the full duration after copying again", async () => {
    const writeText = vi.fn().mockResolvedValue(undefined);
    stubClipboard(writeText);
    const { result } = renderHook(() =>
      useCopyToClipboard({ copiedDuration: 1800 }),
    );

    await act(async () => {
      result.current.copyToClipboard("first");
      await Promise.resolve();
    });
    await act(async () => {
      await vi.advanceTimersByTimeAsync(1000);
    });
    await act(async () => {
      result.current.copyToClipboard("second");
      await Promise.resolve();
    });

    expect(result.current.isCopied).toBe(true);
    await act(async () => {
      await vi.advanceTimersByTimeAsync(1799);
    });
    expect(result.current.isCopied).toBe(true);
    await act(async () => {
      await vi.advanceTimersByTimeAsync(1);
    });
    expect(result.current.isCopied).toBe(false);
    expect(writeText).toHaveBeenNthCalledWith(1, "first");
    expect(writeText).toHaveBeenNthCalledWith(2, "second");
  });

  it("does not show copied when the clipboard write fails", async () => {
    const writeText = vi
      .fn()
      .mockRejectedValue(new Error("clipboard permission denied"));
    stubClipboard(writeText);
    const { result } = renderHook(() => useCopyToClipboard());

    await act(async () => {
      result.current.copyToClipboard("value");
      await Promise.resolve();
    });

    expect(result.current.isCopied).toBe(false);
    expect(vi.getTimerCount()).toBe(0);
    expect(writeText).toHaveBeenCalledWith("value");
  });

  it("does not show copied when the clipboard is unavailable", async () => {
    vi.stubGlobal("navigator", { ...navigator, clipboard: undefined });
    const { result } = renderHook(() => useCopyToClipboard());

    await act(async () => {
      result.current.copyToClipboard("value");
      await Promise.resolve();
    });

    expect(result.current.isCopied).toBe(false);
    expect(vi.getTimerCount()).toBe(0);
  });

  it("clears its timer on unmount", async () => {
    stubClipboard(vi.fn().mockResolvedValue(undefined));
    const { result, unmount } = renderHook(() => useCopyToClipboard());

    await act(async () => {
      result.current.copyToClipboard("value");
      await Promise.resolve();
    });
    expect(vi.getTimerCount()).toBe(1);

    unmount();

    expect(vi.getTimerCount()).toBe(0);
  });

  it("ignores clipboard success after unmount", async () => {
    let resolveCopy!: () => void;
    stubClipboard(
      () =>
        new Promise<void>((resolve) => {
          resolveCopy = resolve;
        }),
    );
    const { result, unmount } = renderHook(() => useCopyToClipboard());

    result.current.copyToClipboard("value");
    unmount();
    resolveCopy();
    await act(async () => {
      await Promise.resolve();
    });

    expect(vi.getTimerCount()).toBe(0);
  });

  // Activity is React 19 only.
  it.skipIf(onReact18)(
    "resets the confirmation when a hidden Activity cancels its timer",
    async () => {
      stubClipboard(vi.fn().mockResolvedValue(undefined));
      let copy!: ReturnType<typeof useCopyToClipboard>;
      const Probe = () => {
        copy = useCopyToClipboard();
        return null;
      };
      const App = ({ mode }: { mode: "visible" | "hidden" }) => (
        <Activity mode={mode}>
          <Probe />
        </Activity>
      );
      const view = render(<App mode="visible" />);

      await act(async () => {
        copy.copyToClipboard("first");
        await Promise.resolve();
      });
      expect(copy.isCopied).toBe(true);

      view.rerender(<App mode="hidden" />);
      view.rerender(<App mode="visible" />);

      expect(copy.isCopied).toBe(false);
      expect(vi.getTimerCount()).toBe(0);

      await act(async () => {
        copy.copyToClipboard("second");
        await Promise.resolve();
      });
      expect(copy.isCopied).toBe(true);
    },
  );
});

import { fireEvent } from "@testing-library/react"
import { useEffect } from "react"
import { click, render } from "../../jest.setup"
import { useCycle } from "../use-cycle"

describe("useCycle", () => {
    test("cycles through given states", () => {
        const results: number[] = []

        const Component = () => {
            const [latest, cycle] = useCycle(1, 2, 3, 4)
            useEffect(() => {
                if (results[results.length - 1] !== latest) results.push(latest)
            }, [latest])

            return <div onClick={() => cycle()} />
        }

        const { container } = render(<Component />)

        click(container.firstChild as Element)
        click(container.firstChild as Element)
        click(container.firstChild as Element)
        click(container.firstChild as Element)

        expect(results).toEqual([1, 2, 3, 4, 1])
    })

    test("jumps to a given index", () => {
        let result: number = 0

        const Component = () => {
            const [latest, cycle] = useCycle(1, 2, 3, 4)
            result = latest
            return <div onClick={() => cycle(2)} />
        }

        const { container } = render(<Component />)
        fireEvent.click(container.firstChild as Element)

        expect(result).toBe(3)
    })

    test("is not functionally bound by the render cycle", () => {
        let result: number = 0

        const Component = () => {
            const [latest, cycle] = useCycle(1, 2, 3, 4)
            result = latest
            return <div onClick={() => (cycle(), cycle())} />
        }

        const { container } = render(<Component />)
        fireEvent.click(container.firstChild as Element)

        expect(result).toBe(3)
    })
})

